-- Collez ce script dans Supabase > SQL Editor > Run
create table if not exists content (name text primary key, data jsonb not null default '{}', updated_at timestamptz default now());
alter table content enable row level security;
create policy "lecture publique" on content for select using (true);
create policy "admin insere" on content for insert to authenticated with check (true);
create policy "admin modifie" on content for update to authenticated using (true) with check (true);

insert into storage.buckets (id, name, public) values ('pdfs','pdfs',true) on conflict (id) do nothing;
create policy "pdf lecture" on storage.objects for select using (bucket_id='pdfs');
create policy "pdf upload" on storage.objects for insert to authenticated with check (bucket_id='pdfs');
create policy "pdf modif" on storage.objects for update to authenticated using (bucket_id='pdfs');
create policy "pdf suppr" on storage.objects for delete to authenticated using (bucket_id='pdfs');

insert into content (name,data) values ('videos', $j${"items": [{"categorie": "Théorie des groupes", "titre": "Théorie des groupes — Application à la chimie", "description": "Série complète de vidéos sur la théorie des groupes et ses applications en chimie.", "url": "https://youtube.com/playlist?list=PLhOO8nxQfxsgV4pL3upAU2WWpA5YlawN_&si=8k5aFPp_c4e2KQu4"}, {"categorie": "Théorie des groupes", "titre": "Hybridation MX6", "description": "Hybridation MX6 expliquée avec la théorie des groupes.", "url": "https://www.youtube.com/watch?v=7PHaQVD6v1Y"}, {"categorie": "Théorie des groupes", "titre": "Hybridation MX5", "description": "Hybridation MX5 expliquée avec la théorie des groupes.", "url": "https://www.youtube.com/watch?v=dKnfxaeaFuw"}, {"categorie": "Philosophie des sciences", "titre": "Les crises épistémologiques", "description": "Les crises épistémologiques dans l’histoire et l’évolution des sciences.", "url": "https://www.youtube.com/watch?v=8JvAKW67AG4"}, {"categorie": "Philosophie des sciences", "titre": "Constante de Planck h", "description": "La constante de Planck et son importance en sciences physiques.", "url": "https://www.youtube.com/watch?v=lxlIyWaIxDU"}, {"categorie": "Devoir surveillé", "titre": "Devoir surveillé — ENSA Oujda", "description": "Module de Chimie : correction du devoir surveillé de l’ENSA Oujda.", "url": "https://www.youtube.com/watch?v=tN2yPs-wD1o"}]}$j$::jsonb) on conflict (name) do nothing;
insert into content (name,data) values ('cours', $j${"items": [{"titre": "Thermochimie – Fascicule n°5", "info": "SMC · S5", "semestre": "S5", "fichier": "/cours/thermochimie.pdf"}, {"titre": "Hydrocarbures et Fonctions Monovalentes", "info": "SMC · S4", "semestre": "S4", "fichier": "/cours/hydrocarbures.pdf"}, {"titre": "Chimie des Solutions", "info": "SMPC · S2", "semestre": "S2", "fichier": "/cours/solutions.pdf"}, {"titre": "Réactions Organiques", "info": "SMC · S6", "semestre": "S6", "fichier": "/cours/reactions-organiques.pdf"}]}$j$::jsonb) on conflict (name) do nothing;
insert into content (name,data) values ('exercices', $j${"items": [{"titre": "Réactions Organiques – Série 3 corrigée", "info": "SMC · S6", "semestre": "S6", "fichier": "/cours/serie3-corrigee.pdf"}, {"titre": "Thermochimie – Série 1 corrigée", "info": "SMC · S5", "semestre": "S5", "fichier": "/cours/thermo-serie1.pdf"}, {"titre": "Chimie des Solutions – Série 2 corrigée", "info": "SMPC · S2", "semestre": "S2", "fichier": "/cours/solutions-serie2.pdf"}]}$j$::jsonb) on conflict (name) do nothing;
insert into content (name,data) values ('annales', $j${"items": [{"titre": "Liaison chimique – Examen", "info": "SMC · S2", "semestre": "S2", "fichier": "/cours/annale-liaison-chimique.pdf"}, {"titre": "Thermochimie – Examen", "info": "SMC · S5", "semestre": "S5", "fichier": "/cours/annale-thermochimie.pdf"}]}$j$::jsonb) on conflict (name) do nothing;
insert into content (name,data) values ('quiz', $j${"themes": [{"titre": "Thermochimie", "questions": [{"question": "Une réaction exothermique est caractérisée par :", "options": ["ΔH > 0", "ΔH < 0", "ΔH = 0"], "bonne": 2, "explication": "Elle libère de la chaleur vers le milieu extérieur : ΔH < 0 (à pression constante)."}, {"question": "L’enthalpie standard de formation d’un corps simple stable à 298 K vaut :", "options": ["0", "−1 kJ/mol", "Elle dépend du corps"], "bonne": 1, "explication": "Par convention, ΔfH° d’un corps simple dans son état stable de référence est nulle."}, {"question": "La loi de Hess repose sur le fait que ΔH est :", "options": ["Dépendante du chemin suivi", "Une fonction d’état", "Toujours négative"], "bonne": 2, "explication": "H est une fonction d’état : ΔH ne dépend que de l’état initial et de l’état final."}, {"question": "À T et P constantes, une transformation est spontanée si :", "options": ["ΔG < 0", "ΔG > 0", "ΔS < 0"], "bonne": 1, "explication": "Le critère de spontanéité à T et P constantes est ΔG < 0."}, {"question": "Le premier principe de la thermodynamique s’écrit :", "options": ["ΔU = Q + W", "ΔU = Q × W", "ΔU = Q − T·ΔS"], "bonne": 1, "explication": "La variation d’énergie interne est égale à la somme de la chaleur et du travail échangés."}]}, {"titre": "Liaison chimique", "questions": [{"question": "Quelle est la géométrie de CO₂ selon VSEPR ?", "options": ["Coudée", "Linéaire", "Trigonale plane"], "bonne": 2, "explication": "CO₂ est de type AX₂ (sans doublet libre sur C) : molécule linéaire."}, {"question": "Quelle est la géométrie de H₂O (AX₂E₂) ?", "options": ["Linéaire", "Tétraédrique", "Coudée"], "bonne": 3, "explication": "Deux doublets liants et deux doublets libres : géométrie coudée (≈ 104,5°)."}, {"question": "Quel élément est le plus électronégatif ?", "options": ["Oxygène", "Chlore", "Fluor"], "bonne": 3, "explication": "Le fluor est l’élément le plus électronégatif de la classification."}, {"question": "L’ordre de liaison de O₂ (théorie des OM) est :", "options": ["1", "2", "3"], "bonne": 2, "explication": "O₂ : (10 − 6)/2 = 2, avec deux électrons célibataires (paramagnétique)."}]}]}$j$::jsonb) on conflict (name) do nothing;
